<section class="admin-panel admin-form-panel"><div class="admin-panel-heading"><div><span class="admin-eyebrow">PUBLIC SITE CONFIGURATION</span><h2>Site Settings</h2></div></div><p class="admin-panel-note">Only approved public branding, contact, social, SEO, footer, demo disclaimer and media settings are editable here. Secrets and demo trading controls remain protected in their existing configuration screens.</p><?php if(empty($isPreview)): ?><form method="post" action="<?= e(admin_url('settings')) ?>" class="admin-form-grid"><?= admin_csrf_field() ?><?php foreach($fields as $key=>$field): ?><label class="<?= in_array($key,['support_address','default_seo_description','demo_disclaimer','risk_warning','social_links'],true)?'admin-field-wide':'' ?>"><?= e($field['label']) ?><?php if(in_array($key,['support_address','default_seo_description','demo_disclaimer','risk_warning','social_links'],true)): ?><textarea name="<?= e($key) ?>" rows="<?= $key==='social_links'?4:3 ?>"><?= e($field['value']) ?></textarea><?php else: ?><input name="<?= e($key) ?>" maxlength="<?= in_array($key,['site_logo','site_favicon'],true)?255:254 ?>" value="<?= e($field['value']) ?>" <?= in_array($key,['support_email'],true)?'type="email"':'' ?>><?php endif; ?><?php if($key==='social_links'): ?><small>JSON object with optional facebook, instagram, linkedin, youtube and x HTTPS URLs. Example: {"instagram":"https://www.instagram.com/your-page"}</small><?php endif; ?><?php if(in_array($key,['site_logo','site_favicon'],true)): ?><small>Reference an uploaded safe CMS image path (JPEG, PNG or WebP). Enter the uploaded path shown after upload.</small><?php endif; ?></label><?php endforeach; ?><div class="admin-form-actions admin-field-wide"><button type="submit" class="admin-button admin-button-primary">Save site settings</button><a class="admin-button" href="<?= e(admin_url('cms/media')) ?>">Upload media</a><?php if(in_array('settings.view',$permissions??[],true)): ?><a class="admin-button" href="<?= e(admin_url('settings?preview=1')) ?>">Preview current settings</a><?php endif; ?></div></form><?php else: ?><div class="admin-alert admin-alert-info">This is a private, temporary view of the current public site settings.</div><a class="admin-button" href="<?= e(admin_url('settings')) ?>">Return to settings</a><?php foreach($fields as $field): ?><article class="admin-setting-preview"><strong><?= e($field['label']) ?></strong><p><?= nl2br(e($field['value'])) ?></p></article><?php endforeach; ?><?php endif; ?><?php if(!empty($previewUrl)): ?><p><a class="admin-button" href="<?= e($previewUrl) ?>" target="_blank" rel="noopener noreferrer">Open protected preview</a></p><?php endif; ?></section>
